const envelope = $input || {};
const text = (value) => (typeof value === 'string' ? value.trim() : '');
const envelopeKeys = new Set(['pluginId', 'widgetId', 'product', 'resource', 'submittedBy', 'submittedAt', 'action', 'fields']);
const unknownEnvelope = Object.keys(envelope).filter((key) => !envelopeKeys.has(key));
if (unknownEnvelope.length) throw new Error('unknown_envelope_fields:' + unknownEnvelope.join(','));
const product = text(envelope.product);
const resource = text(envelope.resource);
const submittedBy = text(envelope.submittedBy);
if (!submittedBy) throw new Error('submitted_by_required');
const fields = envelope.fields && typeof envelope.fields === 'object' && !Array.isArray(envelope.fields) ? envelope.fields : null;
if (!fields) throw new Error('fields_required');
if (product !== 'city') throw new Error('unsupported_product');
if (resource !== 'assets') throw new Error('unsupported_resource');
const recordId = text(fields.asset_id);
if (!/^[A-Za-z0-9_@.:+-]{1,256}$/.test(recordId)) throw new Error('record_id_invalid');
const encodedAssetId = encodeURIComponent(recordId);
const allowed = new Set(["asset_id","file_id","title","description"]);
const unknown = Object.keys(fields).filter((key) => !allowed.has(key));
if (unknown.length) throw new Error('unknown_fields:' + unknown.join(','));
const fileId = text(fields.file_id);
if (!/^[A-Za-z0-9._-]{1,80}$/.test(fileId)) throw new Error('file_id_required');
const title = text(fields.title);
if (title.length > 200) throw new Error('title_max_200');
const description = text(fields.description);
if (description.length > 4000) throw new Error('description_max_4000');
const audit = {
  product, resource, operation: 'assets.document', recordId,
  pluginId: text(envelope.pluginId), widgetId: text(envelope.widgetId),
  submittedBy, submittedAt: text(envelope.submittedAt) || $now,
};

return { recordId, encodedAssetId, fileId, title, description, submitter: submittedBy, audit, operation: 'assets.document' };

const response = $input || {};
const current = response.body;
const action = response.input.input;
const file = response.input.body;
if (response.statusCode !== 200 || !current || typeof current.data !== 'object' || !current.data) throw new Error('asset_not_found');
if (!file || typeof file !== 'object' || !file.id) throw new Error('file_not_found');
const data = current.data;
if (!Number.isInteger(current.version)) throw new Error('record_version_unavailable');
const contentType = String(file.contentType || '').toLowerCase();
const allowedTypes = ['image/png', 'image/jpeg', 'image/webp', 'image/gif', 'application/pdf', 'text/csv', 'text/plain', 'application/json', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'];
if (!allowedTypes.includes(contentType)) throw new Error('unsupported_file_type');
const attachments = Array.isArray(data.attachments) ? data.attachments.filter((entry) => entry && typeof entry === 'object') : [];
const entry = {
  file_id: String(file.id),
  file_name: String(file.filename || action.title || 'document'),
  file_type: contentType,
  kind: contentType.startsWith('image/') ? 'photo' : 'document',
  ...(typeof file.size === 'number' ? { size: file.size } : {}),
  ...(file.checksumSha256 ? { checksum_sha256: String(file.checksumSha256) } : {}),
  ...(action.title ? { title: action.title } : {}),
  ...(action.description ? { description: action.description } : {}),
  uploaded_by: action.submitter,
  uploaded_at: $now,
};
const next = { ...data, attachments: [...attachments, entry] };
return { body: { data: next, ifVersion: current.version, publish: false }, encodedAssetId: action.encodedAssetId, audit: action.audit, document: entry, attachments: attachments.length + 1 };

const response = $input || {};
const state = response.input;
if (response.statusCode !== 200 && response.statusCode !== 201) throw new Error('asset_write_failed');
return {
  operation: 'assets.document',
  asset_id: state.audit.recordId,
  document: state.document,
  attachments: state.attachments,
};
